public String replaceVowels(String s) {
    String result = "";
    for (int i = 0; i < s.length(); i++) {
        char ch = s.charAt(i);
        if (ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u') {
            result += "*";
        } else {
            result += ch;
        }
    }
    return result;
}

